 leaf(base,tip,width,color='#7ca45a'){const a=sub(tip,base),v=[a[2],0,-a[0]],len=Math.hypot(...v)||1,side=v.map(x=>x/len*width),mid=base.map((x,i)=>lerp(x,tip[i],.53));this.poly([base,add(mid,side),tip,sub(mid,side)],color);this.line([base,mid,tip],'#d9e2ae',.55)}
