 stream(points,color='#d7a24b',{count=9,speed=.11,size=.055,phase=0,trail=true}={}){this.line(points,color,1,{alpha:.22,dash:[3,5]});for(let i=0;i<count;i++){let t=(this.time*speed+i/count+phase)%1;this.dot(this.pathPoint(points,t),size,color,{glow:true});if(trail){for(let j=1;j<=2;j++)this.dot(this.pathPoint(points,(t-j*.012+1)%1),size*(1-j*.23),color,{alpha:.4-j*.1})}}}
